#include <iostream>

bool debe_reponer(int disponibles, int minimo) {
    return disponibles <= minimo;
}

int main() {
    const bool menos = debe_reponer(4, 5);
    const bool justo = debe_reponer(5, 5);
    const bool mas = debe_reponer(6, 5);
    std::cout << menos << ':' << justo << ':' << mas;
    return 0;
}

